using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry;
using OpenTelemetry.Trace;
using System.ClientModel;

namespace MyApp.Eval;

[TestClass]
public static class EvalSetup
{
    private static ReportingConfiguration? s_reportingConfig;

    public static ReportingConfiguration ReportingConfig =>
        s_reportingConfig ?? throw new InvalidOperationException("Call Initialize first.");

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://your-resource.openai.azure.com/";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
            ?? "gpt-4o-mini";

        IChatClient chatClient = new AzureOpenAIClient(
            new Uri(endpoint),
            new DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();

        // Quality evaluators — skip Safety per requirements
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
            new CompletenessEvaluator(),
        };

        s_reportingConfig = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(
                context.TestRunResultsDirectory ?? ".",
                "eval-results"),
            chatConfiguration: new ChatConfiguration(chatClient),
            evaluators: evaluators);
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfig is not null)
        {
            await s_reportingConfig.DisposeAsync();
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: validates that the agent emits expected OpenTelemetry spans
/// and captures token usage metadata from chat completions.
/// </summary>
[TestClass]
public class TelemetryTests
{
    [TestMethod]
    public async Task Agent_EmitsExpectedTelemetry()
    {
        var exportedSpans = new List<Activity>();
        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Coach")
            .AddInMemoryExporter(exportedSpans)
            .Build();

        await using var scenario = await EvalSetup.ReportingConfig
            .CreateScenarioRunAsync(
                scenarioName: nameof(Agent_EmitsExpectedTelemetry));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var response = await chatClient.GetResponseAsync(
            "What is a good warm-up routine before a 5K run?");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);

        // Verify telemetry was captured
        tracerProvider.ForceFlush();
        Assert.IsTrue(
            exportedSpans.Count > 0,
            "Expected at least one telemetry span from the chat completion.");

        // Report token usage if available
        var usage = response.Messages
            .LastOrDefault()?.AdditionalProperties?
            .TryGetValue("Usage", out var u) == true ? u : null;

        scenario.Record(
            new EvaluationMetric("TelemetrySpanCount", exportedSpans.Count),
            new EvaluationMetric("ResponseReceived", 1));
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: runs LLM-as-judge evaluators (coherence, relevance,
/// fluency, groundedness, completeness) against agent responses.
/// </summary>
[TestClass]
public class QualityTests
{
    private static IEnumerable<object[]> Scenarios =>
    [
        ["WarmUp", "What is a good warm-up routine before a 5K run?"],
        ["Nutrition", "What should I eat the night before a marathon?"],
        ["Recovery", "How do I recover after a long training run?"],
    ];

    [TestMethod]
    [DynamicData(nameof(Scenarios))]
    public async Task Quality_MeetsThreshold(string scenarioName, string userPrompt)
    {
        await using var scenario = await EvalSetup.ReportingConfig
            .CreateScenarioRunAsync(scenarioName: $"Quality_{scenarioName}");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a running coach. Provide helpful, accurate advice."),
            new(ChatRole.User, userPrompt),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var assistantMessage = response.Messages.Last();

        messages.Add(assistantMessage);

        // Run all configured quality evaluators
        await scenario.EvaluateAsync(messages);

        // Assert quality scores meet minimum thresholds
        foreach (var metric in scenario.GetEvaluationResults())
        {
            if (metric is NumericMetric numeric && numeric.Value.HasValue)
            {
                Assert.IsTrue(
                    numeric.Value >= 3.0,
                    $"Metric '{metric.Name}' scored {numeric.Value:F1}, expected >= 3.0");
            }
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Compare mode: records deterministic scenario results to disk so that
/// successive runs can be diffed via the reporting tool to detect regressions.
/// Run with: dotnet test --filter "TestCategory=Compare"
/// Then view results with: dotnet eval report --results-path ./TestResults/eval-results
/// </summary>
[TestClass]
[TestCategory("Compare")]
public class CompareTests
{
    private static IEnumerable<object[]> BaselineScenarios =>
    [
        ["Baseline_Pacing", "I want to run a sub-20 minute 5K. What pace should I target?"],
        ["Baseline_Injury", "My knee hurts after running. What could be wrong?"],
        ["Baseline_Plan", "Create a 4-week training plan for a beginner half marathon runner."],
    ];

    [TestMethod]
    [DynamicData(nameof(BaselineScenarios))]
    public async Task Compare_AgainstBaseline(string scenarioName, string userPrompt)
    {
        await using var scenario = await EvalSetup.ReportingConfig
            .CreateScenarioRunAsync(scenarioName: scenarioName);

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a running coach. Provide helpful, accurate advice."),
            new(ChatRole.User, userPrompt),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var assistantMessage = response.Messages.Last();

        messages.Add(assistantMessage);

        // Evaluate quality for comparison across runs
        await scenario.EvaluateAsync(messages);

        // Record response length as a stability metric
        scenario.Record(
            new EvaluationMetric(
                "ResponseLength",
                assistantMessage.Text?.Length ?? 0));

        // The reporting infrastructure persists results to disk.
        // Compare across runs using:
        //   dotnet eval report --results-path ./TestResults/eval-results
    }
}

