        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var response = await chatClient.GetResponseAsync(
            "What is a good warm-up routine before a 5K run?");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);

        // Verify telemetry was captured
        tracerProvider.ForceFlush();
        Assert.IsTrue(
            exportedSpans.Count > 0,
            "Expected at least one telemetry span from the chat completion.");

        // Report token usage if available
        var usage = response.Messages
            .LastOrDefault()?.AdditionalProperties?
            .TryGetValue("Usage", out var u) == true ? u : null;

        scenario.Record(
            new EvaluationMetric("TelemetrySpanCount", exportedSpans.Count),
            new EvaluationMetric("ResponseReceived", 1));
    }
}

