using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: runs LLM-as-judge evaluators (coherence, relevance,
/// fluency, groundedness, completeness) against agent responses.
/// </summary>
[TestClass]
public class QualityTests
{
    private static IEnumerable<object[]> Scenarios =>
    [
        ["WarmUp", "What is a good warm-up routine before a 5K run?"],
        ["Nutrition", "What should I eat the night before a marathon?"],
        ["Recovery", "How do I recover after a long training run?"],
    ];

    [TestMethod]
    [DynamicData(nameof(Scenarios))]
    public async Task Quality_MeetsThreshold(string scenarioName, string userPrompt)
    {
        await using var scenario = await EvalSetup.ReportingConfig
            .CreateScenarioRunAsync(scenarioName: $"Quality_{scenarioName}");

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a running coach. Provide helpful, accurate advice."),
            new(ChatRole.User, userPrompt),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var assistantMessage = response.Messages.Last();

        messages.Add(assistantMessage);

        // Run all configured quality evaluators
        await scenario.EvaluateAsync(messages);

        // Assert quality scores meet minimum thresholds
        foreach (var metric in scenario.GetEvaluationResults())
        {
            if (metric is NumericMetric numeric && numeric.Value.HasValue)
            {
                Assert.IsTrue(
                    numeric.Value >= 3.0,
                    $"Metric '{metric.Name}' scored {numeric.Value:F1}, expected >= 3.0");
            }
        }
    }
}

