namespace MyApp.Eval;

/// <summary>
/// Compare mode: records deterministic scenario results to disk so that
/// successive runs can be diffed via the reporting tool to detect regressions.
/// Run with: dotnet test --filter "TestCategory=Compare"
/// Then view results with: dotnet eval report --results-path ./TestResults/eval-results
/// </summary>
[TestClass]
[TestCategory("Compare")]
public class CompareTests
{
    private static IEnumerable<object[]> BaselineScenarios =>
    [
        ["Baseline_Pacing", "I want to run a sub-20 minute 5K. What pace should I target?"],
        ["Baseline_Injury", "My knee hurts after running. What could be wrong?"],
        ["Baseline_Plan", "Create a 4-week training plan for a beginner half marathon runner."],
    ];

    [TestMethod]
    [DynamicData(nameof(BaselineScenarios))]
    public async Task Compare_AgainstBaseline(string scenarioName, string userPrompt)
    {
        await using var scenario = await EvalSetup.ReportingConfig
            .CreateScenarioRunAsync(scenarioName: scenarioName);

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a running coach. Provide helpful, accurate advice."),
            new(ChatRole.User, userPrompt),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var assistantMessage = response.Messages.Last();

        messages.Add(assistantMessage);

        // Evaluate quality for comparison across runs
        await scenario.EvaluateAsync(messages);

        // Record response length as a stability metric
        scenario.Record(
            new EvaluationMetric(
                "ResponseLength",
                assistantMessage.Text?.Length ?? 0));

        // The reporting infrastructure persists results to disk.
        // Compare across runs using:
        //   dotnet eval report --results-path ./TestResults/eval-results
    }
}

